// ─── AI Objection Roleplay ────────────────────────────────────────────────────
const ROLEPLAY_PERSONAS = [
  { id:"busy",    label:"Too Busy",        icon:"⏰", opener:"Ich habe gerade keine Zeit, ich muss gleich in ein Meeting.",                  difficulty:"Easy"   },
  { id:"wife",    label:"Spouse Check",    icon:"💑", opener:"Das muss ich erst mit meiner Frau/meinem Mann besprechen.",                    difficulty:"Medium" },
  { id:"distrust",label:"Skeptic",         icon:"🤨", opener:"Ich bin grundsätzlich skeptisch gegenüber solchen Angeboten.",                  difficulty:"Medium" },
  { id:"price",   label:"Price Objection", icon:"💸", opener:"Das klingt interessant, aber ich glaube, das wird zu teuer für mich sein.",    difficulty:"Hard"   },
  { id:"already", label:"Has Advisor",     icon:"🏦", opener:"Ich habe schon einen Finanzberater und bin damit zufrieden.",                  difficulty:"Hard"   },
  { id:"noknowhow",label:"Not Interested", icon:"🚫", opener:"Ich interessiere mich eigentlich gar nicht für Finanzthemen.",                 difficulty:"Expert" },
];

const AIObjectionRoleplay = () => {
  const [persona,    setPersona]    = useState(null);
  const [messages,   setMessages]   = useState([]);
  const [input,      setInput]      = useState("");
  const [loading,    setLoading]    = useState(false);
  const [sessionEnd, setSessionEnd] = useState(false);
  const [feedback,   setFeedback]   = useState(null);
  const [turnCount,  setTurnCount]  = useState(0);
  const MAX_TURNS = 4;

  const startSession = (p) => {
    setPersona(p);
    setMessages([{ role:"lead", text:p.opener }]);
    setSessionEnd(false);
    setFeedback(null);
    setTurnCount(0);
  };

  const sendReply = async () => {
    if(!input.trim()||loading) return;
    const userMsg = input.trim();
    setInput("");
    const newMessages = [...messages, { role:"gp", text:userMsg }];
    setMessages(newMessages);
    setLoading(true);

    const history = newMessages.map(m=>`${m.role==="gp"?"GP":"Lead"}: ${m.text}`).join("\n");
    const isLast = turnCount + 1 >= MAX_TURNS;

    try {
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method:"POST",
        headers:{ "Content-Type":"application/json" },
        body: JSON.stringify({
          model:"claude-sonnet-4-20250514",
          max_tokens:1000,
          system:`You are roleplaying as a skeptical German lead for a vion financial advisory CRM training session.
Persona: "${persona.label}" — your opening objection was: "${persona.opener}"
Stay in character as this lead. React authentically to what the GP says.
${isLast ? `This is the FINAL exchange. After the GP's response, output EXACTLY this JSON structure (no other text):
{"reaction": "<lead's final reaction in 1 sentence>", "verdict": "<Convinced|Not Convinced|Partial>", "score": <0-100>, "feedback": {"pitch": <0-100>, "empathy": <0-100>, "close": <0-100>}, "coaching": "<2-3 specific coaching sentences for the GP>", "highlight": "<quote the best thing the GP said>", "improve": "<quote what could be improved and why>"}` 
: `Reply as the lead in 1-2 sentences. Stay resistant but authentic. Don't be convinced too easily.`}`,
          messages:[{ role:"user", content: isLast
            ? `Conversation so far:\n${history}\n\nNow output the final JSON evaluation.`
            : `The GP just said: "${userMsg}"\n\nRespond as the lead (1-2 sentences, stay in character).` }],
        })
      });
      const data = await res.json();
      const text = data.content?.[0]?.text || "";

      if(isLast) {
        try {
          const clean = text.replace(/```json|```/g,"").trim();
          const json  = JSON.parse(clean);
          setMessages(prev=>[...prev, { role:"lead", text:json.reaction }]);
          setFeedback(json);
          setSessionEnd(true);
        } catch {
          setMessages(prev=>[...prev, { role:"ai-error", text:"Could not parse evaluation. Try again." }]);
        }
      } else {
        setMessages(prev=>[...prev, { role:"lead", text:text }]);
        setTurnCount(t=>t+1);
      }
    } catch {
      setMessages(prev=>[...prev, { role:"ai-error", text:"API error — check connection." }]);
    }
    setLoading(false);
  };

  if(!persona) return (
    <div style={{ padding:"24px" }}>
      <div style={{ fontSize:14,fontWeight:800,color:C.navy,marginBottom:4 }}>🎭 AI Objection Roleplay</div>
      <div style={{ fontSize:12,color:C.muted,marginBottom:20,lineHeight:1.5,maxWidth:560 }}>
        Practice handling real objections. The AI plays a skeptical lead. You respond as the GP.
        After {MAX_TURNS} exchanges, the AI grades your performance and gives coaching notes.
      </div>
      <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:12 }}>
        {ROLEPLAY_PERSONAS.map(p=>(
          <div key={p.id} onClick={()=>startSession(p)}
            style={{ padding:"16px",borderRadius:12,background:"#fff",border:`1px solid ${C.border}`,
              cursor:"pointer",transition:"all 0.15s" }}
            onMouseEnter={e=>e.currentTarget.style.borderColor=C.ai}
            onMouseLeave={e=>e.currentTarget.style.borderColor=C.border}>
            <div style={{ fontSize:24,marginBottom:8 }}>{p.icon}</div>
            <div style={{ fontSize:13,fontWeight:700,color:C.text,marginBottom:3 }}>{p.label}</div>
            <div style={{ fontSize:11,color:C.muted,marginBottom:8,lineHeight:1.4 }}>"{p.opener.slice(0,60)}…"</div>
            <span style={{ fontSize:10,fontWeight:700,padding:"2px 8px",borderRadius:8,
              background:p.difficulty==="Easy"?C.green+"15":p.difficulty==="Medium"?C.amber+"15":p.difficulty==="Hard"?C.red+"15":"#7C3AED15",
              color:p.difficulty==="Easy"?C.green:p.difficulty==="Medium"?C.amber:p.difficulty==="Hard"?C.red:"#7C3AED" }}>
              {p.difficulty}
            </span>
          </div>
        ))}
      </div>
    </div>
  );

  return (
    <div style={{ padding:"24px" }}>
      <div style={{ display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16 }}>
        <div>
          <div style={{ fontSize:14,fontWeight:800,color:C.navy }}>🎭 Roleplay — {persona.label} {persona.icon}</div>
          <div style={{ fontSize:11,color:C.muted }}>Turn {Math.min(turnCount+1,MAX_TURNS)} of {MAX_TURNS} · Difficulty: {persona.difficulty}</div>
        </div>
        <button onClick={()=>{ setPersona(null); setMessages([]); setSessionEnd(false); setFeedback(null); setTurnCount(0); }}
          style={{ padding:"5px 14px",borderRadius:8,border:`1px solid ${C.border}`,background:"#fff",color:C.muted,fontSize:11,fontWeight:600,cursor:"pointer" }}>
          ← Change Persona
        </button>
      </div>

      {/* Chat */}
      <div style={{ background:"#F8FAFC",borderRadius:12,border:`1px solid ${C.border}`,padding:"16px",marginBottom:14,maxHeight:280,overflowY:"auto",display:"flex",flexDirection:"column",gap:10 }}>
        {messages.map((m,i)=>(
          <div key={i} style={{ display:"flex",justifyContent:m.role==="gp"?"flex-end":"flex-start",gap:8 }}>
            {m.role!=="gp" && <div style={{ width:28,height:28,borderRadius:"50%",background:m.role==="lead"?C.amber+"20":"#F3F4F6",display:"flex",alignItems:"center",justifyContent:"center",fontSize:14,flexShrink:0 }}>{m.role==="lead"?persona.icon:"⚠️"}</div>}
            <div style={{ maxWidth:"75%",padding:"9px 13px",borderRadius:m.role==="gp"?"14px 14px 3px 14px":"14px 14px 14px 3px",
              background:m.role==="gp"?C.ai:"#fff",color:m.role==="gp"?"#fff":C.text,fontSize:12,lineHeight:1.5,
              boxShadow:"0 1px 3px rgba(0,0,0,0.07)" }}>
              {m.role==="lead"&&<div style={{ fontSize:10,fontWeight:700,color:C.amber,marginBottom:3 }}>Lead ({persona.label})</div>}
              {m.role==="gp"&&<div style={{ fontSize:10,fontWeight:700,color:"rgba(255,255,255,0.7)",marginBottom:3 }}>You (GP)</div>}
              {m.text}
            </div>
          </div>
        ))}
        {loading && (
          <div style={{ display:"flex",gap:8 }}>
            <div style={{ width:28,height:28,borderRadius:"50%",background:C.amber+"20",display:"flex",alignItems:"center",justifyContent:"center",fontSize:14 }}>{persona.icon}</div>
            <div style={{ padding:"9px 13px",borderRadius:"14px 14px 14px 3px",background:"#fff",boxShadow:"0 1px 3px rgba(0,0,0,0.07)",display:"flex",gap:4,alignItems:"center" }}>
              {[0,1,2].map(i=><div key={i} style={{ width:6,height:6,borderRadius:"50%",background:C.amber,opacity:0.4+i*0.3 }}/>)}
            </div>
          </div>
        )}
      </div>

      {/* Input */}
      {!sessionEnd && (
        <div style={{ display:"flex",gap:10 }}>
          <input value={input} onChange={e=>setInput(e.target.value)}
            onKeyDown={e=>e.key==="Enter"&&sendReply()}
            placeholder="Type your response as the GP…"
            style={{ flex:1,padding:"10px 14px",borderRadius:9,border:`1.5px solid ${C.border}`,fontSize:13,fontFamily:"inherit",outline:"none" }}/>
          <button onClick={sendReply} disabled={!input.trim()||loading}
            style={{ padding:"10px 20px",borderRadius:9,border:"none",background:input.trim()&&!loading?C.ai:"#E2E8F0",color:input.trim()&&!loading?"#fff":C.muted,fontSize:13,fontWeight:700,cursor:input.trim()&&!loading?"pointer":"default" }}>
            {turnCount+1>=MAX_TURNS?"Finish →":"Reply →"}
          </button>
        </div>
      )}

      {/* AI Feedback */}
      {sessionEnd && feedback && (
        <div style={{ borderRadius:12,border:`2px solid ${C.ai}30`,background:C.ai+"04",padding:"20px",marginTop:8 }}>
          <div style={{ display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16 }}>
            <div style={{ fontSize:14,fontWeight:800,color:C.navy }}>🤖 AI Coach Feedback</div>
            <div style={{ fontSize:28,fontWeight:800,color:feedback.score>=70?C.green:feedback.score>=50?C.amber:C.red }}>{feedback.score}<span style={{ fontSize:16,fontWeight:400,color:C.muted }}>/100</span></div>
          </div>
          <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:10,marginBottom:14 }}>
            {[["Pitch",feedback.feedback?.pitch],["Empathy",feedback.feedback?.empathy],["Close",feedback.feedback?.close]].map(([lbl,val])=>(
              <div key={lbl} style={{ background:"#fff",borderRadius:9,padding:"10px 12px",textAlign:"center",border:`1px solid ${C.border}` }}>
                <div style={{ fontSize:16,fontWeight:800,color:val>=70?C.green:val>=50?C.amber:C.red }}>{val}</div>
                <div style={{ fontSize:10,color:C.muted,marginTop:2 }}>{lbl}</div>
              </div>
            ))}
          </div>
          <div style={{ marginBottom:10,padding:"10px 14px",borderRadius:9,background:C.green+"08",border:`1px solid ${C.green}25`,fontSize:12,color:C.slate }}>
            <strong style={{ color:C.green }}>✅ What worked:</strong> {feedback.highlight}
          </div>
          <div style={{ marginBottom:10,padding:"10px 14px",borderRadius:9,background:C.amber+"08",border:`1px solid ${C.amber}25`,fontSize:12,color:C.slate }}>
            <strong style={{ color:C.amber }}>🔧 Improve:</strong> {feedback.improve}
          </div>
          <div style={{ padding:"10px 14px",borderRadius:9,background:C.ai+"08",border:`1px solid ${C.ai}25`,fontSize:12,color:C.slate }}>
            <strong style={{ color:C.ai }}>📋 Coaching notes:</strong> {feedback.coaching}
          </div>
          <button onClick={()=>startSession(persona)}
            style={{ marginTop:14,width:"100%",padding:"10px",borderRadius:9,border:"none",background:C.ai,color:"#fff",fontSize:13,fontWeight:700,cursor:"pointer" }}>
            🔁 Try Again
          </button>
        </div>
      )}
    </div>
  );
};

// ─── Voice-to-CRM ─────────────────────────────────────────────────────────────
const VoiceToCRM = ({ leads=ALL_LEADS }) => {
  const [step,       setStep]       = useState("idle"); // idle | recording | processing | done
  const [transcript, setTranscript] = useState("");
  const [result,     setResult]     = useState(null);
  const [selectedLead, setSelectedLead] = useState(null);
  const [timer,      setTimer]      = useState(0);
  const timerRef = useRef(null);
  const DEMO_TRANSCRIPTS = [
    "Reached Herr Müller, he's interested in the Gold package, wants a follow-up call next Tuesday at 10am. He asked about monthly returns and seemed very open.",
    "Called Sandra Richter twice, no answer. Left a voicemail. Will try again tomorrow morning.",
    "Appointment with Klaus Weber went well. He signed the consultation agreement. Very happy customer. Will refer a colleague.",
  ];

  const startRecording = () => {
    setStep("recording");
    setTimer(0);
    timerRef.current = setInterval(()=>setTimer(t=>t+1),1000);
    // Auto-stop at 30s in demo
    setTimeout(stopRecording, 6000);
  };

  const stopRecording = () => {
    clearInterval(timerRef.current);
    // Pick a random demo transcript
    const demo = DEMO_TRANSCRIPTS[Math.floor(Math.random()*DEMO_TRANSCRIPTS.length)];
    setTranscript(demo);
    setStep("processing");
    processTranscript(demo);
  };

  const processTranscript = async (text) => {
    try {
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method:"POST",
        headers:{ "Content-Type":"application/json" },
        body: JSON.stringify({
          model:"claude-sonnet-4-20250514",
          max_tokens:1000,
          system:`You are the vion CRM post-call processor. Given a GP's dictated call note, extract structured data.
Output ONLY valid JSON, no markdown:
{"status": "<in_progress|not_reached|appointment|customer|followup|not_interested>", "lifecycle": "<Nurturing|Qualifying|Sales|Won|Lost>", "summary": "<professional 1-2 sentence summary>", "nextAction": "<specific next action>", "nextDate": "<e.g. Tuesday 10:00|Tomorrow morning|Immediately>", "sentiment": "<Positive|Neutral|Negative>", "keyPoints": ["<point1>","<point2>"]}`,
          messages:[{ role:"user", content:`Dictated call note: "${text}"` }],
        })
      });
      const data = await res.json();
      const text2 = data.content?.[0]?.text || "{}";
      const json  = JSON.parse(text2.replace(/```json|```/g,"").trim());
      setResult(json);
      setStep("done");
    } catch {
      setResult({ status:"in_progress", lifecycle:"Qualifying", summary:text, nextAction:"Review manually", nextDate:"ASAP", sentiment:"Neutral", keyPoints:[] });
      setStep("done");
    }
  };

  const statusColors = { in_progress:C.blue, not_reached:C.red, appointment:C.purple, customer:C.green, followup:C.amber, not_interested:C.muted };

  return (
    <div style={{ padding:"24px" }}>
      <div style={{ fontSize:14,fontWeight:800,color:C.navy,marginBottom:4 }}>🎙️ Voice-to-CRM</div>
      <div style={{ fontSize:12,color:C.muted,marginBottom:20,lineHeight:1.5,maxWidth:560 }}>
        Dictate your call notes aloud — AI automatically formats them, sets the lead status, and creates the next follow-up action. No typing needed.
      </div>

      {/* Lead selector */}
      <div style={{ marginBottom:16 }}>
        <label style={{ fontSize:11,fontWeight:700,color:C.muted,textTransform:"uppercase",letterSpacing:"0.05em",display:"block",marginBottom:6 }}>Lead (optional — links note to lead)</label>
        <div style={{ position:"relative" }}>
          <select value={selectedLead||""} onChange={e=>setSelectedLead(e.target.value||null)}
            style={{ width:"100%",padding:"9px 30px 9px 12px",borderRadius:9,border:`1.5px solid ${C.border}`,fontSize:13,fontFamily:"inherit",appearance:"none",outline:"none",background:"#fff" }}>
            <option value="">— No lead selected —</option>
            {leads.slice(0,8).map(l=><option key={l.id} value={l.id}>{l.name}</option>)}
          </select>
          <div style={{ position:"absolute",right:10,top:"50%",transform:"translateY(-50%)",pointerEvents:"none",fontSize:10,color:C.muted }}>▼</div>
        </div>
      </div>

      {/* Recording UI */}
      {step==="idle" && (
        <div style={{ textAlign:"center",padding:"32px 20px",background:"#F8FAFC",borderRadius:14,border:`1px dashed ${C.border}` }}>
          <div style={{ fontSize:48,marginBottom:12 }}>🎙️</div>
          <div style={{ fontSize:14,fontWeight:700,color:C.text,marginBottom:6 }}>Tap to start recording</div>
          <div style={{ fontSize:12,color:C.muted,marginBottom:20 }}>Speak your call notes naturally — AI does the rest</div>
          <button onClick={startRecording}
            style={{ padding:"12px 32px",borderRadius:24,border:"none",background:C.red,color:"#fff",fontSize:14,fontWeight:700,cursor:"pointer",display:"inline-flex",alignItems:"center",gap:8 }}>
            ⏺ Start Recording
          </button>
        </div>
      )}

      {step==="recording" && (
        <div style={{ textAlign:"center",padding:"32px 20px",background:"#FFF5F5",borderRadius:14,border:`2px solid ${C.red}40` }}>
          <div style={{ fontSize:48,marginBottom:8 }}>🔴</div>
          <div style={{ fontSize:16,fontWeight:800,color:C.red }}>{String(Math.floor(timer/60)).padStart(2,"0")}:{String(timer%60).padStart(2,"0")}</div>
          <div style={{ fontSize:13,color:C.red,marginBottom:4,fontWeight:600 }}>Recording…</div>
          <div style={{ fontSize:12,color:C.muted,marginBottom:20 }}>Speak clearly — "Called Herr Müller, interested in Gold package…"</div>
          <div style={{ display:"flex",justifyContent:"center",gap:3,marginBottom:20 }}>
            {Array.from({length:12}).map((_,i)=>(
              <div key={i} style={{ width:4,borderRadius:2,background:C.red,
                height:8+Math.sin(Date.now()/200+i)*8,opacity:0.5+Math.sin(i)*0.5,transition:"height 0.1s" }}/>
            ))}
          </div>
          <button onClick={stopRecording}
            style={{ padding:"12px 32px",borderRadius:24,border:"none",background:"#fff",color:C.red,border:`2px solid ${C.red}`,fontSize:14,fontWeight:700,cursor:"pointer" }}>
            ⏹ Stop
          </button>
        </div>
      )}

      {step==="processing" && (
        <div style={{ padding:"20px",borderRadius:12,background:"#F8FAFC",border:`1px solid ${C.border}` }}>
          <div style={{ marginBottom:12 }}>
            <div style={{ fontSize:11,fontWeight:700,color:C.muted,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:5 }}>Transcript</div>
            <div style={{ fontSize:13,color:C.slate,lineHeight:1.6,fontStyle:"italic" }}>"{transcript}"</div>
          </div>
          <div style={{ display:"flex",alignItems:"center",gap:10,color:C.ai,fontSize:13,fontWeight:600 }}>
            <div style={{ display:"flex",gap:4 }}>{[0,1,2].map(i=><div key={i} style={{ width:7,height:7,borderRadius:"50%",background:C.ai,opacity:0.4+i*0.3 }}/>)}</div>
            AI is classifying your call note…
          </div>
        </div>
      )}

      {step==="done" && result && (
        <>
          <div style={{ padding:"12px 14px",borderRadius:9,background:"#F8FAFC",border:`1px solid ${C.border}`,marginBottom:14 }}>
            <div style={{ fontSize:11,fontWeight:700,color:C.muted,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:5 }}>Transcript</div>
            <div style={{ fontSize:12,color:C.slate,fontStyle:"italic" }}>"{transcript}"</div>
          </div>
          <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:14 }}>
            {[
              ["📊 Status",      result.status?.replace(/_/g," ")||"—",  statusColors[result.status]||C.muted],
              ["🔄 Lifecycle",   result.lifecycle||"—",                   C.indigo],
              ["😊 Sentiment",   result.sentiment||"—",                   result.sentiment==="Positive"?C.green:result.sentiment==="Negative"?C.red:C.amber],
              ["📅 Next action", result.nextDate||"—",                    C.navy],
            ].map(([lbl,val,col])=>(
              <div key={lbl} style={{ padding:"10px 14px",borderRadius:9,background:"#fff",border:`1px solid ${C.border}` }}>
                <div style={{ fontSize:10,color:C.muted,marginBottom:3 }}>{lbl}</div>
                <div style={{ fontSize:13,fontWeight:700,color:col,textTransform:"capitalize" }}>{val}</div>
              </div>
            ))}
          </div>
          <div style={{ padding:"12px 14px",borderRadius:9,background:C.ai+"06",border:`1px solid ${C.ai}25`,marginBottom:12 }}>
            <div style={{ fontSize:11,fontWeight:700,color:C.ai,marginBottom:4 }}>🤖 Professional Summary</div>
            <div style={{ fontSize:13,color:C.slate,lineHeight:1.5 }}>{result.summary}</div>
          </div>
          {result.keyPoints?.length>0 && (
            <div style={{ marginBottom:12 }}>
              <div style={{ fontSize:11,fontWeight:700,color:C.muted,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:6 }}>Key points</div>
              {result.keyPoints.map((p,i)=>(
                <div key={i} style={{ display:"flex",gap:8,marginBottom:5,fontSize:12,color:C.slate }}>
                  <span style={{ color:C.green,fontWeight:700,flexShrink:0 }}>✓</span>{p}
                </div>
              ))}
            </div>
          )}
          <div style={{ padding:"10px 14px",borderRadius:9,background:C.amber+"08",border:`1px solid ${C.amber}30`,marginBottom:14,fontSize:12,color:C.slate }}>
            <strong style={{ color:C.amber }}>⚡ Next:</strong> {result.nextAction} — {result.nextDate}
          </div>
          <div style={{ display:"flex",gap:10 }}>
            <button onClick={()=>alert("Call note saved to CRM and lead status updated.")}
              style={{ flex:2,padding:"10px",borderRadius:9,border:"none",background:C.navy,color:"#fff",fontSize:13,fontWeight:700,cursor:"pointer" }}>
              ✅ Save to CRM
            </button>
            <button onClick={()=>{ setStep("idle"); setTranscript(""); setResult(null); }}
              style={{ flex:1,padding:"10px",borderRadius:9,border:`1px solid ${C.border}`,background:"#fff",color:C.muted,fontSize:13,fontWeight:600,cursor:"pointer" }}>
              🔁 Redo
            </button>
          </div>
        </>
      )}
    </div>
  );
};

// ─── AI Meeting Prep Brief ─────────────────────────────────────────────────────
const AIMeetingPrepBrief = ({ leads=ALL_LEADS }) => {
  const apptLeads = leads.filter(l=>l.status==="appointment"||l.status==="in_progress");
  const [selected,   setSelected]   = useState(null);
  const [brief,      setBrief]      = useState(null);
  const [loading,    setLoading]    = useState(false);

  const generateBrief = async (lead) => {
    setSelected(lead);
    setBrief(null);
    setLoading(true);
    const ai = AI_SCORES?.[lead.id];
    const bt = AI_BEST_TIMES?.[lead.id];

    try {
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method:"POST",
        headers:{ "Content-Type":"application/json" },
        body: JSON.stringify({
          model:"claude-sonnet-4-20250514",
          max_tokens:1200,
          system:`You are an AI assistant for vion CRM, a German financial advisory platform. Generate a concise pre-meeting brief for a GP advisor.
Output ONLY valid JSON:
{"headline": "<1 sentence executive summary>", "leadProfile": "<2-3 sentences about this lead's background, interests, and situation>", "keyObjectives": ["<objective 1>","<objective 2>","<objective 3>"], "openingLine": "<specific suggested opening line for the meeting>", "anticipatedObjections": [{"objection":"<likely objection>","response":"<suggested response>"}], "productMatch": {"primary":"<best fitting product>","reason":"<why it fits>","secondary":"<alternative product>"}, "doList": ["<do this>","<and this>"], "dontList": ["<avoid this>","<and this>"], "closingStrategy": "<specific closing technique to use>"}`,
          messages:[{ role:"user", content:`Generate meeting prep brief for: Name: ${lead.name}, Status: ${lead.status}, Product: ${lead.product}, Source: ${lead.source||"Unknown"}, City: ${lead.city}, Attempts: ${lead.attempts||0}, AI Score: ${ai?.score||"N/A"}, Score reason: ${ai?.reasons?.[0]||"N/A"}, Language: ${lead.lang==="en"?"English":"German"}` }],
        })
      });
      const data = await res.json();
      const text = data.content?.[0]?.text||"{}";
      const json = JSON.parse(text.replace(/```json|```/g,"").trim());
      setBrief(json);
    } catch {
      setBrief({ headline:`Meeting prep for ${lead.name}`, leadProfile:"AI brief unavailable — check API connection.", keyObjectives:["Build rapport","Present value proposition","Handle objections"], openingLine:"Guten Tag, schön Sie kennenzulernen.", anticipatedObjections:[], productMatch:{primary:lead.product,reason:"Based on profile",secondary:"—"}, doList:["Listen actively","Ask about goals"], dontList:["Don't rush the close"], closingStrategy:"Ask for a follow-up commitment" });
    }
    setLoading(false);
  };

  return (
    <div style={{ padding:"24px" }}>
      <div style={{ fontSize:14,fontWeight:800,color:C.navy,marginBottom:4 }}>📋 AI Meeting Prep Brief</div>
      <div style={{ fontSize:12,color:C.muted,marginBottom:20,lineHeight:1.5,maxWidth:560 }}>
        Before your next appointment, generate a 1-page AI briefing — lead profile, best opening line, anticipated objections, and product match.
      </div>

      {/* Lead selector */}
      {!brief && !loading && (
        <div style={{ display:"flex",flexDirection:"column",gap:8 }}>
          {(apptLeads.length?apptLeads:leads).slice(0,6).map(lead=>{
            const ai = AI_SCORES?.[lead.id];
            return (
              <div key={lead.id} onClick={()=>generateBrief(lead)}
                style={{ display:"flex",alignItems:"center",gap:14,padding:"13px 16px",
                  borderRadius:11,background:"#fff",border:`1px solid ${C.border}`,cursor:"pointer" }}>
                <Avatar name={lead.name} size={38}/>
                <div style={{ flex:1 }}>
                  <div style={{ fontSize:13,fontWeight:700,color:C.text }}>{lead.name}</div>
                  <div style={{ fontSize:11,color:C.muted }}>{lead.product} · {lead.city} · {lead.status?.replace(/_/g," ")}</div>
                </div>
                {ai && <div style={{ textAlign:"right",flexShrink:0 }}>
                  <div style={{ fontSize:14,fontWeight:800,color:ai.score>=70?C.green:ai.score>=50?C.amber:C.red }}>{ai.score}</div>
                  <div style={{ fontSize:9,color:C.muted }}>AI score</div>
                </div>}
                <span style={{ fontSize:13,color:C.ai,fontWeight:700 }}>Generate →</span>
              </div>
            );
          })}
        </div>
      )}

      {loading && (
        <div style={{ padding:"40px",textAlign:"center",background:"#F8FAFC",borderRadius:12,border:`1px solid ${C.border}` }}>
          <div style={{ fontSize:32,marginBottom:12 }}>📋</div>
          <div style={{ fontSize:14,fontWeight:700,color:C.ai,marginBottom:4 }}>Generating brief for {selected?.name}…</div>
          <div style={{ fontSize:12,color:C.muted }}>Analysing lead profile, history, and best matching products…</div>
        </div>
      )}

      {brief && selected && (
        <>
          {/* Header */}
          <div style={{ display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16 }}>
            <div style={{ display:"flex",alignItems:"center",gap:10 }}>
              <Avatar name={selected.name} size={40}/>
              <div>
                <div style={{ fontSize:15,fontWeight:800,color:C.navy }}>{selected.name}</div>
                <div style={{ fontSize:11,color:C.muted }}>{brief.headline}</div>
              </div>
            </div>
            <button onClick={()=>{ setBrief(null); setSelected(null); }}
              style={{ padding:"5px 12px",borderRadius:8,border:`1px solid ${C.border}`,background:"#fff",color:C.muted,fontSize:11,fontWeight:600,cursor:"pointer" }}>← Back</button>
          </div>

          {/* Brief sections */}
          <div style={{ display:"flex",flexDirection:"column",gap:12 }}>
            {/* Lead profile */}
            <div style={{ padding:"14px 16px",borderRadius:11,background:"#fff",border:`1px solid ${C.border}` }}>
              <div style={{ fontSize:11,fontWeight:700,color:C.muted,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:6 }}>👤 Lead Profile</div>
              <div style={{ fontSize:12,color:C.slate,lineHeight:1.6 }}>{brief.leadProfile}</div>
            </div>

            {/* Opening line */}
            <div style={{ padding:"14px 16px",borderRadius:11,background:C.ai+"06",border:`1px solid ${C.ai}25` }}>
              <div style={{ fontSize:11,fontWeight:700,color:C.ai,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:6 }}>🎙️ Suggested Opening Line</div>
              <div style={{ fontSize:13,color:C.text,fontStyle:"italic",lineHeight:1.5 }}>"{brief.openingLine}"</div>
            </div>

            {/* Product match */}
            <div style={{ padding:"14px 16px",borderRadius:11,background:C.green+"06",border:`1px solid ${C.green}25` }}>
              <div style={{ fontSize:11,fontWeight:700,color:C.green,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:8 }}>📦 Best Product Match</div>
              <div style={{ display:"flex",gap:10 }}>
                <div style={{ flex:1,padding:"10px",borderRadius:8,background:C.green+"10",border:`1px solid ${C.green}30`,textAlign:"center" }}>
                  <div style={{ fontSize:13,fontWeight:800,color:C.green }}>{brief.productMatch?.primary}</div>
                  <div style={{ fontSize:10,color:C.muted,marginTop:2 }}>Primary match</div>
                  <div style={{ fontSize:11,color:C.slate,marginTop:4 }}>{brief.productMatch?.reason}</div>
                </div>
                <div style={{ flex:1,padding:"10px",borderRadius:8,background:"#F8FAFC",border:`1px solid ${C.border}`,textAlign:"center" }}>
                  <div style={{ fontSize:13,fontWeight:700,color:C.slate }}>{brief.productMatch?.secondary}</div>
                  <div style={{ fontSize:10,color:C.muted,marginTop:2 }}>Alternative</div>
                </div>
              </div>
            </div>

            {/* Objectives + objections in 2-col */}
            <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr",gap:12 }}>
              <div style={{ padding:"14px 16px",borderRadius:11,background:"#fff",border:`1px solid ${C.border}` }}>
                <div style={{ fontSize:11,fontWeight:700,color:C.muted,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:8 }}>🎯 Key Objectives</div>
                {(brief.keyObjectives||[]).map((o,i)=>(
                  <div key={i} style={{ display:"flex",gap:8,marginBottom:6,fontSize:12,color:C.slate }}>
                    <span style={{ color:C.navy,fontWeight:700,flexShrink:0 }}>{i+1}.</span>{o}
                  </div>
                ))}
              </div>
              <div style={{ padding:"14px 16px",borderRadius:11,background:"#fff",border:`1px solid ${C.border}` }}>
                <div style={{ fontSize:11,fontWeight:700,color:C.muted,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:8 }}>🛡️ Anticipated Objections</div>
                {(brief.anticipatedObjections||[]).slice(0,2).map((obj,i)=>(
                  <div key={i} style={{ marginBottom:8 }}>
                    <div style={{ fontSize:11,fontWeight:600,color:C.red,marginBottom:2 }}>"{obj.objection}"</div>
                    <div style={{ fontSize:11,color:C.slate,lineHeight:1.4 }}>→ {obj.response}</div>
                  </div>
                ))}
              </div>
            </div>

            {/* Do/Don't */}
            <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr",gap:12 }}>
              <div style={{ padding:"12px 14px",borderRadius:10,background:C.green+"06",border:`1px solid ${C.green}25` }}>
                <div style={{ fontSize:10,fontWeight:700,color:C.green,marginBottom:6,textTransform:"uppercase" }}>✅ Do</div>
                {(brief.doList||[]).map((d,i)=><div key={i} style={{ fontSize:11,color:C.slate,marginBottom:4 }}>• {d}</div>)}
              </div>
              <div style={{ padding:"12px 14px",borderRadius:10,background:C.red+"06",border:`1px solid ${C.red}25` }}>
                <div style={{ fontSize:10,fontWeight:700,color:C.red,marginBottom:6,textTransform:"uppercase" }}>🚫 Avoid</div>
                {(brief.dontList||[]).map((d,i)=><div key={i} style={{ fontSize:11,color:C.slate,marginBottom:4 }}>• {d}</div>)}
              </div>
            </div>

            {/* Closing strategy */}
            <div style={{ padding:"12px 16px",borderRadius:10,background:C.purple+"06",border:`1px solid ${C.purple}25` }}>
              <div style={{ fontSize:10,fontWeight:700,color:C.purple,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:4 }}>🏁 Closing Strategy</div>
              <div style={{ fontSize:12,color:C.slate,lineHeight:1.5 }}>{brief.closingStrategy}</div>
            </div>

            {/* Actions */}
            <div style={{ display:"flex",gap:10 }}>
              <button onClick={()=>alert("Brief saved to lead profile and synced to Calendar.")}
                style={{ flex:2,padding:"10px",borderRadius:9,border:"none",background:C.navy,color:"#fff",fontSize:13,fontWeight:700,cursor:"pointer" }}>
                💾 Save to Lead Profile
              </button>
              <button onClick={()=>generateBrief(selected)}
                style={{ flex:1,padding:"10px",borderRadius:9,border:`1px solid ${C.border}`,background:"#fff",color:C.muted,fontSize:13,fontWeight:600,cursor:"pointer" }}>
                🔁 Refresh
              </button>
            </div>
          </div>
        </>
      )}
    </div>
  );
};

const AIInsightsTab = ({ role }) => {
  const [emailLead, setEmailLead]   = useState(null);
  const [emailCopied, setEmailCopied] = useState(false);
  const [aiSubTab,  setAiSubTab]    = useState("insights"); // insights | roleplay | voice | brief
  const myLeads   = ALL_LEADS.filter(l=>l.assignedGP==="Anna Klein");
  const myVDLeads = ALL_LEADS.filter(l=>l.assignedGP==="Thomas Müller");
  const emailDraft = emailLead ? (AI_EMAIL_DRAFTS[emailLead.id]||AI_EMAIL_DRAFTS.default) : null;

  const copyEmail = () => {
    if(emailDraft) { navigator.clipboard?.writeText(`${emailDraft.subject}\n\n${emailDraft.body}`).catch(()=>{}); setEmailCopied(true); setTimeout(()=>setEmailCopied(false),2000); }
  };

  const SUB_TABS = [
    { id:"insights",  label:"📊 Insights",       desc:"Scores, timing, email drafts"    },
    { id:"roleplay",  label:"🎭 Objection Roleplay", desc:"Practice with AI as lead"     },
    { id:"voice",     label:"🎙️ Voice-to-CRM",    desc:"Dictate call notes"             },
    { id:"brief",     label:"📋 Meeting Prep",    desc:"AI brief before appointments"   },
  ];

  return (
    <div style={{ padding:"24px 0" }}>
      {/* Sub-tab nav */}
      <div style={{ display:"flex",gap:8,marginBottom:24,flexWrap:"wrap" }}>
        {SUB_TABS.map(t=>(
          <button key={t.id} onClick={()=>setAiSubTab(t.id)}
            style={{ padding:"8px 16px",borderRadius:9,border:`1.5px solid ${aiSubTab===t.id?C.ai:C.border}`,
              background:aiSubTab===t.id?C.ai+"08":"#fff",
              color:aiSubTab===t.id?C.ai:C.muted,
              fontSize:12,fontWeight:aiSubTab===t.id?700:400,cursor:"pointer",fontFamily:"inherit",
              display:"flex",flexDirection:"column",alignItems:"flex-start",gap:2,minWidth:130 }}>
            <span style={{ fontSize:13 }}>{t.label}</span>
            <span style={{ fontSize:10,color:aiSubTab===t.id?C.ai:C.muted,fontWeight:400 }}>{t.desc}</span>
          </button>
        ))}
      </div>

      {/* New AI features */}
      {aiSubTab==="roleplay" && <AIObjectionRoleplay/>}
      {aiSubTab==="voice"    && <VoiceToCRM leads={role==="gp"?myLeads:myVDLeads}/>}
      {aiSubTab==="brief"    && <AIMeetingPrepBrief leads={role==="gp"?myLeads:myVDLeads}/>}

      {/* Existing insights grid */}
      {aiSubTab==="insights" && (
      <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr",gap:16 }}>

        {/* Best Contact Time */}
        <div style={{ padding:"20px 24px",borderRadius:12,background:"#fff",border:`1px solid ${C.border}` }}>
          <div style={{ fontSize:13,fontWeight:800,color:C.text,marginBottom:4 }}>⏰ Best Contact Windows</div>
          <div style={{ fontSize:11,color:C.muted,marginBottom:14 }}>AI analysis of ZIP code + campaign reach patterns + time-of-day data.</div>
          {(role==="gp"?myLeads:myVDLeads).filter(l=>AI_BEST_TIMES[l.id]).slice(0,4).map((l)=>{
            const bt=AI_BEST_TIMES[l.id];
            return (
              <div key={l.id} style={{ padding:"11px 14px",borderRadius:10,border:`1px solid ${C.border}`,background:"#FAFAFA",marginBottom:8,display:"flex",gap:12,alignItems:"center" }}>
                <Avatar name={l.name} size={32} />
                <div style={{ flex:1 }}>
                  <div style={{ fontSize:12,fontWeight:700,color:C.text }}>{l.name}</div>
                  <div style={{ fontSize:11,color:C.muted,marginTop:1 }}>{bt.reason}</div>
                </div>
                <div style={{ textAlign:"right",flexShrink:0 }}>
                  <div style={{ fontSize:13,fontWeight:800,color:C.navy }}>{bt.window}</div>
                  <div style={{ fontSize:10,color:C.muted }}>{bt.day} · {bt.confidence}% match</div>
                </div>
              </div>
            );
          })}
        </div>

        {/* Email Draft Generator */}
        <div style={{ padding:"20px 24px",borderRadius:12,background:"#fff",border:`1px solid ${C.border}` }}>
          <div style={{ fontSize:13,fontWeight:800,color:C.text,marginBottom:4 }}>✉️ AI Email Drafts</div>
          <div style={{ fontSize:11,color:C.muted,marginBottom:14 }}>Personalised follow-up emails per lead. Review, edit, then send.</div>
          <div style={{ display:"flex",flexDirection:"column",gap:6,marginBottom:emailLead?14:0 }}>
            {(role==="gp"?myLeads:myVDLeads).filter(l=>!["closed","no_interest"].includes(l.status)).slice(0,4).map(l=>(
              <div key={l.id} onClick={()=>setEmailLead(l===emailLead?null:l)} style={{ padding:"9px 14px",borderRadius:9,border:`1.5px solid ${emailLead?.id===l.id?C.ai:C.border}`,background:emailLead?.id===l.id?C.ai+"08":"#FAFAFA",cursor:"pointer",display:"flex",alignItems:"center",gap:10 }}>
                <Avatar name={l.name} size={28} />
                <div style={{ flex:1 }}><div style={{ fontSize:12,fontWeight:700,color:C.text }}>{l.name}</div><div style={{ fontSize:11,color:C.muted }}>{l.campaign}</div></div>
                <span style={{ fontSize:11,color:emailLead?.id===l.id?C.ai:C.muted,fontWeight:700 }}>{emailLead?.id===l.id?"▲ Hide":"Draft →"}</span>
              </div>
            ))}
          </div>
          {emailLead && emailDraft && (
            <div style={{ padding:"14px",borderRadius:10,background:C.ai+"06",border:`1.5px solid ${C.ai}25`,marginTop:6 }}>
              <div style={{ display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10 }}>
                <div style={{ fontSize:11,fontWeight:700,color:C.ai }}>🤖 Generated for {emailLead.name}</div>
                <span style={{ fontSize:10,padding:"2px 8px",borderRadius:10,background:C.ai+"15",color:C.ai,fontWeight:700 }}>{emailDraft.tone}</span>
              </div>
              <div style={{ fontSize:11,fontWeight:700,color:C.muted,textTransform:"uppercase",marginBottom:4 }}>Subject</div>
              <div style={{ padding:"7px 10px",borderRadius:6,background:"#fff",border:`1px solid ${C.border}`,fontSize:12,fontWeight:600,color:C.text,marginBottom:10 }}>{emailDraft.subject}</div>
              <div style={{ fontSize:11,fontWeight:700,color:C.muted,textTransform:"uppercase",marginBottom:4 }}>Body</div>
              <pre style={{ padding:"10px 12px",borderRadius:6,background:"#fff",border:`1px solid ${C.border}`,fontSize:11,color:C.slate,lineHeight:1.7,whiteSpace:"pre-wrap",fontFamily:"inherit",margin:"0 0 12px" }}>{emailDraft.body}</pre>
              <div style={{ display:"flex",gap:8 }}>
                <button onClick={copyEmail} style={{ flex:1,padding:"8px",borderRadius:7,border:"none",background:emailCopied?C.green:C.ai,color:"#fff",fontSize:11,fontWeight:700,cursor:"pointer" }}>{emailCopied?"✓ Copied!":"📋 Copy Email"}</button>
                <button style={{ padding:"8px 14px",borderRadius:7,border:`1px solid ${C.border}`,background:"#fff",color:C.slate,fontSize:11,fontWeight:600,cursor:"pointer" }}>✏️ Edit</button>
                <button style={{ padding:"8px 14px",borderRadius:7,border:"none",background:C.green,color:"#fff",fontSize:11,fontWeight:700,cursor:"pointer" }}>📤 Send</button>
              </div>
            </div>
          )}
        </div>

      </div>
      )} {/* end aiSubTab==="insights" */}
    </div>
  );
};
const AnalyticsTab = ({ role }) => {
  const [activeReport, setActiveReport] = useState(null);
  const isVD = role==="vd";
  const REPORTS = [
    { key:"vd_performance", icon:"👥", title:isVD?"Team Performance":"VD Performance Report",   desc:"Director comparison: leads, appointments, closings and conversion rates.",     color:C.navy   },
    { key:"campaign_roi",   icon:"📣", title:"Campaign & Source ROI",    desc:"Lead volume, cost-per-lead, and conversion by campaign and source channel.",    color:C.indigo },
    { key:"appointments",   icon:"📅", title:"Appointment Analytics",    desc:"Booking rate, show rate, cancellation rate by VD, GP, and campaign.",          color:C.blue   },
    { key:"closing",        icon:"✅", title:"Closing & Revenue Report", desc:"Closed deals, deal value, cycle length, and revenue attribution.",              color:C.green  },
    { key:"gdpr",           icon:"🔒", title:"GDPR Compliance",          desc:"Consent rates, opt-out trends, retargeting eligibility and retention.",        color:C.purple },
    { key:"email",          icon:"✉️", title:"Email Automation Stats",   desc:"Open rates, click rates, and conversion by automated journey.",                color:C.amber  },
  ];
  const quickMetrics = isVD
    ? [{label:"Team Leads",value:"890",color:C.navy},{label:"Appointments",value:"54",color:C.indigo},{label:"Closed",value:"34",color:C.green},{label:"Not Reached",value:"125",color:C.red},{label:"Opt-in Rate",value:"76.4%",color:C.purple},{label:"Conv. Rate",value:"7.1%",color:C.amber}]
    : [{label:"Total Leads",value:"2.904",color:C.navy},{label:"Appointments",value:"134",color:C.indigo},{label:"Closed",value:"89",color:C.green},{label:"Not Reached",value:"203",color:C.red},{label:"Opt-in Rate",value:"79.8%",color:C.purple},{label:"Conv. Rate",value:"6.2%",color:C.amber}];
  if(activeReport) return <ReportDetail report={activeReport} role={role} onBack={()=>setActiveReport(null)} />;
  return (
    <div style={{ padding:"24px 0" }}>
      <div style={{ display:"grid",gridTemplateColumns:"repeat(6,1fr)",gap:12,marginBottom:20 }}>
        {quickMetrics.map(k=>(
          <div key={k.label} style={{ padding:"14px",borderRadius:10,background:k.color+"08",border:`1px solid ${k.color}20`,textAlign:"center" }}>
            <div style={{ fontSize:10,color:C.muted,fontWeight:700,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:6 }}>{k.label}</div>
            <div style={{ fontSize:20,fontWeight:800,color:k.color }}>{k.value}</div>
          </div>
        ))}
      </div>
      <div style={{ display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:14 }}>
        {REPORTS.map(s=>(
          <div key={s.key} style={{ padding:"20px",borderRadius:12,background:"#fff",border:`1px solid ${C.border}`,cursor:"pointer" }}
            onMouseEnter={e=>e.currentTarget.style.boxShadow="0 4px 20px rgba(0,0,0,0.08)"}
            onMouseLeave={e=>e.currentTarget.style.boxShadow="none"}>
            <div style={{ width:38,height:38,borderRadius:10,background:s.color+"15",display:"flex",alignItems:"center",justifyContent:"center",fontSize:18,marginBottom:12 }}>{s.icon}</div>
            <div style={{ fontSize:14,fontWeight:700,color:C.text,marginBottom:5 }}>{s.title}</div>
            <div style={{ fontSize:12,color:C.muted,lineHeight:1.5,marginBottom:14 }}>{s.desc}</div>
            <button onClick={()=>setActiveReport(s)} style={{ padding:"6px 12px",borderRadius:7,border:"none",background:s.color,color:"#fff",fontSize:11,fontWeight:700,cursor:"pointer" }}>View Report →</button>
          </div>
        ))}
      </div>
    </div>
  );
};

